5	export const paymentSuccessEndpoint = onRequest(
6	  { cors: ['*'] },
7	  async (request, response) => {
8	    try {
9	      const { payment_intent, metadata }: PaymentResponseObject =
10	        request.body.data.object;
11	      const userId = metadata['userId'];
12	      const listingId = metadata['listingId'];
13	      const listingSnapshot = await firestore()
14	        .collection('listings')
15	        .doc(listingId)
16	        .get();
17	      const listingData = listingSnapshot.data() as Listing;
18	      const numberOfShares = metadata['numberOfShares'];
19	
20	      const newInvestment: Investment = {
21	        userId,
22	        listingId,
23	        numberOfShares: parseInt(numberOfShares),
24	        createdAt: +new Date(),
25	        appreciationRate: listingData?.expectedAppreciationRate || 0,
26	        name: listingData?.title || '',
27	        category: listingData?.category || 'antiques',
28	        action: 'buy',
29	        paymentIntentId: payment_intent,
30	      };
31	      console.log({ newInvestment });
32	
33	      await firestore().collection('investments').add(newInvestment);
34	
35	      response.status(200).send('Submitted successfully');
36	    } catch (error) {
37	      console.error(error);
38	      response.status(500).send('Error');
39	    }
40	  },
41	);
