14	export function useInvestment(id: string, action: InvestmentAction) {
15	  const userId = useRecoilValue(userIdAtom);
16	  const userEmail = useRecoilValue(userEmailAtom);
17	  const { data: listingData, isPending: isListingPending } = useListingItem(id);
18	  const { data: settings } = useSettings();
19	
20	  const userNumberOfShares = useMemo(
21	    () =>
22	      settings?.shares?.find((share) => share.listingID === id)?.numberOfShares,
23	    [settings, id],
24	  );
25	  const shareOptions = useMemo(
26	    () => getShareOptions(action, listingData, userNumberOfShares),
27	    [action, listingData, userNumberOfShares],
28	  );
29	  const latestMarketPrice = useMemo(
30	    () => listingData?.marketPrices?.findLast((item) => item)?.price || 0,
31	    [listingData?.marketPrices],
32	  );
33	  const newPricePerShare = useMemo(
34	    () => latestMarketPrice / listingData?.totalNumberOfShares,
35	    [latestMarketPrice, listingData?.totalNumberOfShares],
36	  );
37	
38	  const createNewInvestment = useMutation({
39	    mutationFn: (newItem: Investment) => {
40	      const db = new FirestoreCollection<Investment>(`investments`);
41	      return db.add(newItem);
42	    },
43	    onSuccess: () => {
44	      toast.success(
45	        `You have successfully ${action === 'buy' ? 'invested in' : 'sold shares of'} ${listingData?.title}.`,
46	      );
47	    },
48	    onError: (error: FirebaseError) => {
49	      console.error(
50	        `Error ${action === 'buy' ? 'creating' : 'selling'} investment:`,
51	        error.message,
52	      );
53	      toast.error(`Something went wrong. Please try again.`);
54	    },
55	  });
56	
57	  const createCheckout = useMutation({
58	    mutationFn: async () => {
59	      const pricePerShare =
60	        action === 'sell' ? newPricePerShare : listingData?.pricePerShare || 0;
61	      const data = await createStripeCheckout({
62	        userEmail: userEmail || '',
63	        userId: userId || '',
64	        numberOfShares: state.option,
65	        listingId: listingData?.id || id,
66	        data: {
67	          currency: 'eur',
68	          unit_amount: pricePerShare * state.option * 100,
69	          product_data: {
70	            name: `${state.option} share${state.option > 1 ? 's' : ''} of ${listingData?.title}`,
71	            description: `${listingData?.description || ''}`,
72	          },
73	        },
74	      });
75	      if (!data?.success || !data?.url) {
76	        toast.error('Something went wrong. Please try again.');
77	        return;
78	      }
79	      window.location.href = data.url;
80	      return;
81	    },
82	    onSuccess: () => {
83	      if (action === 'buy') return;
84	      toast.success(
85	        `You have successfully sold shares of ${listingData?.title}.`,
86	      );
87	    },
88	    onError: (error: FirebaseError) => {
89	      console.error(
90	        `Error ${action === 'buy' ? 'creating' : 'selling'} investment:`,
91	        error.message,
92	      );
93	      toast.error(`Something went wrong. Please try again.`);
94	    },
95	  });
96	
97	  const { state, validation, update, validate, validateForm } =
98	    useForm<InvestmentForm>({
99	      option: 1,
100	    });
101	
102	  async function handleSubmit() {
103	    if (!id) return null;
104	    if (!validateForm()) {
105	      toast.error('Please select number of shares that you want to buy.');
106	      return;
107	    }
108	    if (action === 'sell' && !userNumberOfShares) {
109	      toast.error('You do not have any shares in this listing to sell.');
110	      return;
111	    }
112	    if (action === 'buy') {
113	      createCheckout.mutateAsync();
114	      return;
115	    }
116	    createNewInvestment.mutateAsync({
117	      userId: userId || '',
118	      listingId: id,
119	      numberOfShares: state.option || 0,
120	      createdAt: +new Date(),
121	      appreciationRate: listingData?.expectedAppreciationRate || 0,
122	      name: listingData?.title || '',
123	      category: listingData?.category || 'antiques',
124	      action: action,
125	    });
126	    return;
127	  }
128	
129	  return {
130	    listingData,
131	    validation,
132	    state,
133	    shareOptions,
134	    userNumberOfShares,
135	    newPricePerShare,
136	    isLoading:
137	      createNewInvestment.isPending ||
138	      isListingPending ||
139	      createCheckout.isPending,
140	    update,
141	    handleSubmit,
142	    validate,
143	  };
144	}
